//! Shared caller preparation/recovery for reactive host adapters. A prepared
//! mutation owns its signed bytes and is never regenerated by transport retry.
const std = @import("std");
const root = @import("root.zig");
const r = root.ReactiveModel;
const m = root.Model;
const p = root.protocol;
const Self = @This();
wire: *root.station.client.Client,
connection: Connection,
key: p.Ed25519.KeyPair,
pub const Connection = struct { realm: u64, principal: u64, service: u64, ingress: u64 };
/// Deliberately excludes publication, policy, observer and application commands.
pub const Command = union(enum) {
    open: r.Open,
    attach: r.Attach,
    subscribe: r.Subscribe,
    renew: @FieldType(r.Command, "renew"),
    unsubscribe: @FieldType(r.Command, "unsubscribe"),
    close: r.SessionIdentity,
    pub fn native(self: Command) r.Command {
        return switch (self) {
            inline else => |value, tag| @unionInit(r.Command, @tagName(tag), value),
        };
    }
};
pub const Observation = union(enum) { pending, committed, rejected: p.Value };
pub const Request = union(enum) {
    describe,
    inspect: r.Read,
    covered: struct { observation: root.TableWatch.Observation, captured: root.query.fuze.Unified.Basis },
    prepare: Command,
    submit: r.SignedSend,
    observe: u64,
    sign_read: r.Read,
};
pub const Response = union(enum) {
    description: struct { connection: Connection, discovery: root.Api.Discovery, max_lease_ms: u32 = r.max_lease_ms },
    inspection: struct { response: root.ReactiveAdapter.Response, observation: root.TableWatch.Observation },
    covered: bool,
    prepared: r.SignedSend,
    receipt: root.Adapter.Receipt,
    observation: Observation,
    signed_read: r.SignedRead,
};
fn query(self: Self, kind: @FieldType(p.Growth.Query, "kind")) !p.Growth.Response {
    const signed = try p.Growth.signQuery(.{ .realm = self.connection.realm, .principal = self.connection.principal, .kind = kind }, self.key);
    const response = try self.wire.call(p.Growth.Response, "/v3/query", signed);
    try p.Growth.validateResponse(response, signed.query);
    return response;
}
pub fn prepare(self: Self, command: Command) !r.SignedSend {
    inline for (.{ "realm", "principal", "service", "ingress" }) |name| try m.identity(@field(self.connection, name));
    const current = try self.query(.{ .identity = {} });
    if (current.body.identity.pid != self.connection.ingress) return error.ServingDenied;
    return self.prepareAt(command, try std.math.add(u64, current.principal_sequence, 1));
}
/// Explicit sequence is useful to a host that already owns a serialized caller
/// session. It grants no authority and cannot advance native sequence state.
pub fn prepareAt(self: Self, command: Command, sequence: u64) !r.SignedSend {
    try m.identity(sequence);
    const payload = try (m.Command{ .reactive = command.native() }).encode();
    const value = try (root.station.Frame{ .kind = .cast, .payload = payload }).encode();
    const signed = try p.Growth.sign(.{ .realm = self.connection.realm, .principal = self.connection.principal, .sequence = sequence, .command = .{ .send = .{ .pid = self.connection.ingress, .value = value } } }, self.key);
    return .{ .request = .{ .realm = signed.request.realm, .principal = signed.request.principal, .sequence = sequence, .command = .{ .send = signed.request.command.send } }, .signature = signed.signature };
}
pub fn validate(self: Self, prepared: r.SignedSend) !void {
    const request = prepared.native();
    if (request.request.realm != self.connection.realm or request.request.principal != self.connection.principal or request.request.command.send.pid != self.connection.ingress) return error.ServingDenied;
    try p.Ed25519.Signature.fromBytes(prepared.signature).verify(&try p.Growth.digest(request.request), self.key.public_key);
    const frame = try root.station.Frame.decode(request.request.command.send.value);
    if (frame.kind != .cast) return error.InvalidServingCommand;
    const command = try m.Command.decode(frame.payload);
    if (command != .reactive) return error.InvalidServingCommand;
    switch (command.reactive) {
        .open, .attach, .subscribe, .renew, .unsubscribe, .close => {},
        else => return error.InvalidServingCommand,
    }
}
pub fn signRead(self: Self, read: r.Read) !r.SignedRead {
    const scope = read.scope;
    if (scope.realm != self.connection.realm or scope.principal != self.connection.principal or scope.service != self.connection.service or scope.ingress != self.connection.ingress) return error.ServingDenied;
    return r.SignedRead.sign(read, self.key);
}
pub fn observe(self: Self, adapter: root.Adapter, input: u64) !Observation {
    try m.identity(input);
    const signed = try m.SignedRead.sign(.{ .realm = self.connection.realm, .principal = self.connection.principal, .service = self.connection.service, .ingress = self.connection.ingress, .kind = .disposition, .operation = input }, self.key);
    // Current service/native/resource policy before and after the input check.
    _ = try adapter.read(signed, self.key.public_key.toBytes());
    const current = try self.query(.{ .process = self.connection.ingress });
    if (input > current.position) return error.InvalidServingReceipt;
    const state = current.body.process;
    if (state.process.lifecycle != .running or state.process.failure != null) return error.ResourceUnavailable;
    const result = try adapter.read(signed, self.key.public_key.toBytes());
    if (state.input) |head| if (head.position <= input) return .pending;
    return if (result.disposition) |reason| .{ .rejected = reason } else .committed;
}
pub fn apply(self: Self, adapter: root.Adapter, request: Request) !Response {
    return switch (request) {
        .describe, .inspect => error.ReactiveAdapterRequired,
        .covered => |input| .{ .covered = root.TableWatch.covered(input.observation, input.captured) },
        .prepare => |command| .{ .prepared = try self.prepare(command) },
        .submit => |prepared| blk: {
            try self.validate(prepared);
            break :blk .{ .receipt = try adapter.submit(prepared.native(), self.key.public_key.toBytes()) };
        },
        .observe => |input| .{ .observation = try self.observe(adapter, input) },
        .sign_read => |read| .{ .signed_read = try self.signRead(read) },
    };
}
test "reactive caller freezes native identity and excludes ambient administrative authority" {
    const t = std.testing;
    const key = try p.Ed25519.KeyPair.generateDeterministic(@splat(27));
    const client: Self = .{ .wire = undefined, .connection = .{ .realm = 49, .principal = 65536, .service = 1, .ingress = 7 }, .key = key };
    const prepared = try client.prepareAt(.{ .open = .{ .session = 19, .source_revision = 1, .lease_before_ms = 1000 } }, 22);
    try client.validate(prepared);
    const frame = try root.station.Frame.decode(prepared.request.command.send.value);
    try t.expectEqual(@as(u64, 19), (try m.Command.decode(frame.payload)).reactive.open.session);
    var changed = prepared;
    changed.request.sequence += 1;
    try t.expectError(error.SignatureVerificationFailed, client.validate(changed));
    changed = prepared;
    changed.request.principal += 1;
    try t.expectError(error.ServingDenied, client.validate(changed));
    const admin = try p.Growth.sign(.{ .realm = 49, .principal = 65536, .sequence = 22, .command = .{ .send = .{ .pid = 7, .value = try (root.station.Frame{ .kind = .cast, .payload = try (m.Command{ .reactive = .{ .observe_clock = 123 } }).encode() }).encode() } } }, key);
    changed = prepared;
    changed.request.command.send = admin.request.command.send;
    changed.signature = admin.signature;
    try t.expectError(error.InvalidServingCommand, client.validate(changed));
    try t.expectError(error.ServingDenied, client.signRead(.{ .scope = .{ .realm = 49, .principal = 65537, .service = 1, .ingress = 7, .session = 19, .generation = 30 }, .kind = .session }));
}
